import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"todo 42 条分类（2026-10-16 用户执行单）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/todo-triage-2026-10-16.md","filePath":"zh/todo-triage-2026-10-16.md"}'),r={name:"zh/todo-triage-2026-10-16.md"};function c(i,t,s,n,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="todo-42-条分类-2026-10-16-用户执行单" tabindex="-1">todo 42 条分类（2026-10-16 用户执行单） <a class="header-anchor" href="#todo-42-条分类-2026-10-16-用户执行单" aria-label="Permalink to &quot;todo 42 条分类（2026-10-16 用户执行单）&quot;">​</a></h1><blockquote><p><strong>历史快照，仅供存档</strong>（DOC-01）：本文行号是 2026-10-16 生成时的 <code>todo.md</code> 行号，此后已随新增条目漂移，不再按此行号派工；当前权威清单是仓根 <code>todo.md</code>（不在 docs 树内，此处不作站内链接），判定以条目原文为准。 口径：把 <code>todo.md</code> 42 条未完成逐条归入 A（可直接实现）/ B（需用户环境或用户拍板）/ C（已被代验可关闭）。 红线照执行单：C 类勾选必须给证据（场景名或测试文件 file:line），不许为清账而勾。 本版结论 <strong>C 为空集</strong>，理由见下节；用户点名的 6 条（37/39/57/62/65/67）括注里确有「已代验」，但每条的括注自身同时保留了「需装机半」——按 todo.md 自带的验收口径「改了未验不算完成」，勾账即自我矛盾。故 6 条落 B，并在 B 表内单列「已代验半证据」与「装机清单对应行」。 行号为本文生成时 <code>todo.md</code> 的行号；新增或删除 todo 行会导致漂移，判定时以条目原文为准。</p></blockquote><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类</th><th>条数</th><th>分布</th></tr></thead><tbody><tr><td>A 可直接实现</td><td>5</td><td>Phase 5「完善组件目录与用户体验」全部（todo.md:184-188）</td></tr><tr><td>B 需用户环境或用户拍板</td><td>37</td><td>MVP 21（:37-83）+ 后续可选 1（:91）+ 验收 3（:96-99）+ Phase 4 六条（:175-180，需拍板）+ Phase 6 六条（:192-197，真机验收）</td></tr><tr><td>C 已被代验可关闭</td><td>0</td><td>无一条满足「证据覆盖整行」</td></tr></tbody></table><h2 id="为什么-c-是空集" tabindex="-1">为什么 C 是空集 <a class="header-anchor" href="#为什么-c-是空集" aria-label="Permalink to &quot;为什么 C 是空集&quot;">​</a></h2><p>判定标准：一条能进 C，要求已有代验证据覆盖该行的<strong>全部</strong>验收口径。逐条核下来：</p><ol><li>21 条 MVP 未完成项的括注全部以「需装机半」收尾，且多数同时依赖真实凭据（:44/:46/:48/:54/:99）或物理硬件（:70/:71）或 OS 面行为（:37/:57/:96/:97）。CI 证据（<code>daily-build</code> 视觉取证工件，断言失败即红构建）只覆盖机械半。</li><li>用户点名的 6 条是「证据最充分」的一组，仍不满足整行覆盖： <ul><li>todo.md:37 进程半已代验（场景 E1 进程数恒 1），气泡呈现属 OS Toast 面（E1b 已建探测、无头会话不可见降级 warning，run 38619441591）。</li><li>todo.md:39 位置还原 + 拖动手势链已代验（场景 R/R3，run 38750239155），跨 DPI 拓扑需物理多屏。</li><li>todo.md:57 AUMID 自愈半已代验（场景 F5t，预删注册键后 <code>Initialize()</code> 重建，run 38494525200），点击/激活路由属 OS Toast 面。</li><li>todo.md:62 缓存无白屏 + Esc 键盘关闭已代验（场景 K3 硬断言，run 38743014862），100ms 精确计时需秒表。</li><li>todo.md:65 空白穿透宿主裁决已代验（H5b <code>WM_NCHITTEST</code>：tile 行=HTCLIENT、外框空白环带=HTTRANSPARENT，run 38750239155），真实鼠标落到下层窗的观感需装机。</li><li>todo.md:67 位置还原 + 二选一 + 拖放链已代验（场景 H/H6，run 38750239155），手感需装机。</li></ul></li><li>引擎层证据确实齐全（<code>tests/Beacon.Core.Tests/EventBusTests.cs:9</code> Publish_InvokesAllSubscribers、<code>:25</code> HandlerException_DoesNotAffectOtherSubscribers、<code>:38</code> Unsubscribe_StopsDelivery、<code>:52</code> 发布快照语义、<code>:86</code> SubscribeOnUi_MarshalsToDispatcher；<code>tests/Beacon.Core.Tests/NotificationEngineTests.cs</code> 引擎去重与冷却），但这几项被 todo.md 已勾选行（:58/:59）消费，不落在 42 条未完成里。</li></ol><p>结论：清账式勾选 6 条会同时违背执行单红线与 todo.md 自身验收口径，不做。若你认为其中某条的装机半已可放弃（例如把「气泡观感」「100ms 计时」降级为不做），那是验收口径变更，需你明确说，我按新口径勾并注明。</p><h2 id="a-类-5-条-phase-5-完善组件目录与用户体验" tabindex="-1">A 类（5 条）：Phase 5 完善组件目录与用户体验 <a class="header-anchor" href="#a-类-5-条-phase-5-完善组件目录与用户体验" aria-label="Permalink to &quot;A 类（5 条）：Phase 5 完善组件目录与用户体验&quot;">​</a></h2><p>前置事实：Phase 2 已把设计令牌与词汇件备齐（<code>ComponentFeedback</code> 四词汇件 Empty/Loading/Error/Offline 已落地但无调用面，<code>docs/design/redesign-2026-10-16-组件库落地.md</code>；<code>SampleGalleryWindow</code> 已有 14 工厂实样证明面），所以 A 类主要是<strong>把已备的件接到真实面</strong>，不是从零造件。</p><table tabindex="0"><thead><tr><th>行号</th><th>条目</th><th>实现要点</th><th>本地门禁</th></tr></thead><tbody><tr><td>187</td><td>统一的空数据、离线与错误状态</td><td>把 <code>ComponentFeedback</code> 四件接到 QuickPanel 空区与 Detail 无数据态，替换现行「空区隐藏 + XAML 横幅」两套口径；接面后删掉重复文案分支</td><td>Core 纯函数无改动即无新单测；App 侧人工核 + CI</td></tr><tr><td>185</td><td>更丰富的布局与条件显示</td><td><code>ComponentLayout</code> 现有 Row/Columns/SectionLabel/When 之外的 Column 词汇件补调用面；条件显示按状态字段驱动而非写死</td><td>布局不变量已有守（<code>ComponentLayerInvariantTests</code>），新增形状补一例</td></tr><tr><td>184</td><td>时间线、表格、图表与趋势组件</td><td>新增 3 个组件工厂（时间线走事件历史、表格走 payload 多行、图表走趋势序列）；数据源走既有绑定引擎（state / selector / const 三态），不引入新 Provider</td><td>各配 1 组 Core 侧解析与空态单测</td></tr><tr><td>186</td><td>组件实例编辑、尺寸调整与桌面布局配置</td><td>设置页新增实例面（组件树编辑、尺寸档、桌面布局区）；写入走既有 <code>Config.UpsertWidget</code> + 树校验 fail-closed 口径</td><td>校验分支补 Storage 侧单测</td></tr><tr><td>188</td><td>主题、密度与可访问性完善</td><td>密度刻度（紧凑/常规）接 <code>DesignTokens</code> 间距刻度；可访问性补齐 UIA 名称与焦点序（现行坑：Border 只设 AutomationId 不进 UIA 树，须 <code>SetName</code> 造 peer）</td><td>UIA 名称补齐后场景 X 类断言需同步核对</td></tr></tbody></table><p>优先级顺序：187 → 185 → 184 → 186 → 188。理由：187 是纯接面、无新语义，风险最低；185 依赖 187 的状态语义；184 三个新件面最大但纯增量；186 牵动设置页与配置面（改动面最广，放后）；188 的可访问性补齐要在前四项的新件面落定后一次收口，否则返工。</p><p><strong>卡点（本机 Linux）</strong>：App 侧（<code>src/Beacon.App/</code>，WinUI 3）在 Linux 编不了——<code>XamlCompiler</code> 先于 <code>Csc</code> 死，本地无 C# 门禁，App 改动只能人工核 + CI（<code>windows-latest</code>）验证。Core / Storage 侧单测可本地跑全量。这不是卡住，是既定交付面：历次 App 改动均走此路径落地。</p><h2 id="b-类-37-条-用户需要提供什么" tabindex="-1">B 类（37 条）：用户需要提供什么 <a class="header-anchor" href="#b-类-37-条-用户需要提供什么" aria-label="Permalink to &quot;B 类（37 条）：用户需要提供什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需要用户提供</th><th>覆盖行号</th><th>具体缺什么</th><th>已代验半（证据）</th></tr></thead><tbody><tr><td>真实 GitHub PAT</td><td>44, 46, 48, 54, 99</td><td>一个可 revoke 的真实 PAT + 有 PR 与 Actions 活动的真实仓库</td><td>mock 链路场景 D；API 层假 Handler 单测（GitHubPullRequestsProviderTests 18 例、GitHubActionsProviderTests 9 例、GitHubApiClientTests 10 例、GitHubWorkflowExecutorTests 6 例）；映射层表驱动</td></tr><tr><td>真实厂商 API 与认证字段</td><td>91</td><td>厂商私有打包工具的 API 文档、认证字段名、额度口径</td><td>开源标准 API 的 Jenkins Provider 已落位（<code>jenkins.build</code>）</td></tr><tr><td>装机观感 / 计时 / 发声目检</td><td>37, 52, 57, 60, 62, 65, 67, 73, 75, 79, 80, 97</td><td>有头桌面会话：气泡/Toast 呈现、默认浏览器跳转、秒表测 100ms、听声、托盘图标目检、刷新不抢焦点的手感</td><td>E1 进程半、F5t AUMID 自愈半、K3 Esc 键盘关闭、H1 前台不变、H5b <code>WM_NCHITTEST</code> 穿透裁决、G7a tile 层反映、G4/G5 改色、G6/G7b/G7c/V2 脉冲四半、V1/V2/V4 注入与通知链（run 见各括注）</td></tr><tr><td>物理或虚拟显示栈（多屏、不同 DPI、拔插）</td><td>39, 70, 71</td><td>至少两块缩放不同的屏；CI 是单屏会话，拓扑事件不可驱动</td><td>R/R3 位置与拖动链、H/H6 悬浮拖放与还原（run 38750239155）</td></tr><tr><td>真人全流程操作流</td><td>74, 82, 83</td><td>干净 Windows 11 虚拟机 + 录屏；RFC §6.2.7 四条含真实网络与真人步骤</td><td>截图已归档 <code>visual-evidence</code> 工件；缓存水合全周期单测已过</td></tr><tr><td>用户拍板（HTML 边界裁定）</td><td>175, 176, 177, 178, 179, 180</td><td>Phase 4 开工前须先出架构决策：仓内有反向记录（<code>docs/master-plan.md:769</code>），设计稿关于「已有实现」的断言约六成在仓内确有其事、两处基本前提大面积查无</td><td>无（决策前不动代码）</td></tr><tr><td>真机回归验收</td><td>192, 193, 194, 195, 196, 197</td><td>依赖 A 类落地 + Phase 4 拍板后，走装机清单 71 条与场景取证回归</td><td>装机 71 条清单已就位（<code>docs/acceptance-checklist.md</code>），CI 视觉取证场景 A-Z 已是回归门</td></tr></tbody></table><h2 id="与-todo-md-的同步口径" tabindex="-1">与 todo.md 的同步口径 <a class="header-anchor" href="#与-todo-md-的同步口径" aria-label="Permalink to &quot;与 todo.md 的同步口径&quot;">​</a></h2><ul><li>本文不勾选任何 todo 行（C 为空集）。</li><li>B 类行不动原文（各括注已自带「已代验半 + 需装机半」，与本文 B 表一致）。</li><li>A 类按优先级逐条落地，每条落地后在 <code>todo.md</code> 对应行括号内补 commit hash 并勾选，与 Phase 0-3 同口径。</li><li>装机半清掉时，<code>docs/acceptance-checklist.md</code> 对应行的日期注记同步补上。</li></ul>',17)])])}const b=d(r,[["render",c]]);export{u as __pageData,b as default};
